<?php /** @var array $languages @var array $pages @var int $selectedPage @var string $selectedLocale @var array|null $translation @var \Core\Security\Csrf $csrf @var string $basePath */ $source=array_values(array_filter($pages,fn(array $p):bool=>(int)$p['id']===$selectedPage))[0]??null; ?>
<section class="status-strip"><div class="status-chip"><strong><?= count($languages) ?></strong><span>Languages</span></div><div class="status-chip"><strong><?= count($pages) ?></strong><span>Source pages</span></div><?php if($source&&$selectedLocale): ?><div class="status-chip ok"><strong><?= e(strtoupper($selectedLocale)) ?></strong><span>Editing translation</span></div><?php endif; ?></section>
<div class="section-grid">
<section class="card"><div class="card-heading"><div><h2>Choose content</h2><p class="card-subtitle">Select a page and language to create or continue a translation.</p></div></div><form method="get" class="inline-fields" action="<?= e_attr($basePath) ?>/admin/translations"><div><label>Source page</label><select name="page_id" required><option value="">Choose page</option><?php foreach($pages as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $selectedPage===(int)$p['id']?'selected':'' ?>><?= e($p['title']) ?></option><?php endforeach; ?></select></div><div><label>Language</label><select name="locale" required><option value="">Choose language</option><?php foreach($languages as $language): ?><option value="<?= e_attr($language['locale']) ?>" <?= $selectedLocale===$language['locale']?'selected':'' ?>><?= e($language['name']) ?> (<?= e($language['locale']) ?>)</option><?php endforeach; ?></select></div><button class="btn secondary">Load editor</button></form></section>
<section class="card"><div class="card-heading"><div><h2>Add a language</h2><p class="card-subtitle">Use a standard locale such as <code>fr</code>, <code>es</code>, or <code>es-mx</code>.</p></div></div><form method="post" class="inline-fields" action="<?= e_attr($basePath) ?>/admin/translations"><?= $csrf->field() ?><input type="hidden" name="action" value="language"><div><label>Locale</label><input name="locale" pattern="[A-Za-z]{2,3}(-[A-Za-z]{2,4})?" placeholder="fr" required></div><div><label>Language name</label><input name="name" placeholder="French" required></div><button class="btn">Add language</button></form></section>
</div>
<?php if($source&&$selectedLocale): ?><section class="card"><div class="card-heading"><div><h2>Translate “<?= e($source['title']) ?>”</h2><p class="card-subtitle">Blank metadata falls back safely, but translated titles and paths should be intentional.</p></div><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/pages/edit/<?= (int)$selectedPage ?>">Open source page</a></div><form method="post" data-busy-label="Saving translation…"><?= $csrf->field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="page_id" value="<?= (int)$selectedPage ?>"><input type="hidden" name="locale" value="<?= e_attr($selectedLocale) ?>"><div class="grid2"><div><label>Translated title</label><input name="title" value="<?= e_attr($translation['title']??'') ?>" placeholder="<?= e_attr($source['title']) ?>" required></div><div><label>Translated URL slug</label><div class="input-prefix"><span>/<?= e($selectedLocale) ?>/</span><input name="slug" value="<?= e_attr($translation['slug']??'') ?>" placeholder="translated-page" required></div></div></div><label>Translated page content</label><textarea name="body" rows="10"><?= e($translation['body']??$source['body']??'') ?></textarea><div class="grid2"><div><label>Search title</label><input name="meta_title" maxlength="70" value="<?= e_attr($translation['meta_title']??'') ?>"></div><div><label>Search description</label><textarea name="meta_description" maxlength="180" rows="3"><?= e($translation['meta_description']??'') ?></textarea></div></div><details class="disclosure"><summary class="btn secondary">Advanced visual-block data</summary><div class="disclosure-body"><p class="field-note">Edit JSON only when translating content stored in visual blocks. Invalid JSON will be rejected.</p><textarea name="blocks_json" rows="10"><?= e($translation['blocks_json']??$source['blocks_json']??'[]') ?></textarea></div></details><input type="hidden" name="schema_json" value="<?= e_attr($translation['schema_json']??$source['schema_json']??'') ?>"><div class="action-bar"><span>Saving updates only this locale.</span><button class="btn">Save translation</button></div></form></section><?php else: ?><div class="empty-state"><strong>Choose a page and language</strong><span>The translation editor will open here without changing the source page.</span></div><?php endif; ?>
